def run(goal, max_steps=5):
    history = [f"Goal: {goal}"]
    for step in range(max_steps):
        out = fake_llm(history, step)          # {thought, action, args}
        if out["action"] == "finish":
            print("Final:", out["args"]["answer"]); return
        fn = TOOLS.get(out["action"])
        obs = fn(**out["args"]) if fn else {"error": "no such tool"}
        print(f"{step + 1}. {out['action']} -> {json.dumps(obs)}")
        history += [out["thought"], json.dumps(obs)]
    print("Stopped: max_steps")

